INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(33491462, 'Snowdrop the Rikka Fairy', '六花精雪花莲', '六花精スノードロップ', 'Effect Monster', 'Plant', 'WATER', 8, 1200, 2600, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上1只植物族怪兽解放才能发动。这张卡和1只植物族怪兽从手卡特殊召唤。这个效果的发动后，直到回合结束时自己不是植物族怪兽不能特殊召唤。 ②：以自己场上1只植物族怪兽为对象才能发动。自己场上的全部植物族怪兽的等级直到回合结束时变成和作为对象的怪兽的等级相同。'),
(67675300, 'Snowdust Dragon', '雪尘龙', 'スノーダスト・ドラゴン', 'Effect Monster', 'Dragon', 'WATER', 8, 2800, 1800, '这张卡可以把场上4个冰指示物取除，从手卡特殊召唤。只要这张卡在场上表侧表示存在，这张卡以外的有冰指示物放置的怪兽不能攻击，也不能作表示形式的变更。'),
(73659078, 'Snowdust Giant', '雪尘巨人', 'スノーダスト・ジャイアント', 'XYZ Monster', 'Beast-Warrior', 'WATER', 4, 2200, 800, '水属性4星怪兽×2 1回合1次，把这张卡1个超量素材取除才能发动。手卡的水属性怪兽任意数量给对方观看，给人观看的数量的冰指示物给场上表侧表示存在的怪兽放置。只要这张卡在场上表侧表示存在，水属性以外的场上的怪兽的攻击力下降场上的冰指示物数量×200的数值。'),
(15893860, 'Snowman Creator', '雪人制造机', 'スノーマン・クリエイター', 'Effect Monster', 'Machine', 'WATER', 4, 1600, 1000, '①：这张卡召唤·反转召唤·特殊召唤成功时才能发动。自己场上的水属性怪兽数量的冰指示物给对方场上的表侧表示怪兽放置。这个效果把冰指示物3个以上放置的场合，可以再选对方场上1张卡破坏。'),
(91133740, 'Snowman Eater', '雪人食人怪', 'スノーマンイーター', 'Effect Monster', 'Aqua', 'WATER', 3, NULL, 1900, '这张卡反转时，选择场上表侧表示存在的1只怪兽破坏。'),
(62370023, 'Snowman Effect', '滚雪人效应', 'スノーマン・エフェクト', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升那只怪兽以外的自己场上的怪兽的原本攻击力的合计数值。这张卡发动的回合，作为对象的怪兽不能直接攻击。'),
(60228941, 'Snoww, Unlight of Dark World', '暗黑界的术师 丝诺', '暗黒界の術師 スノウ', 'Effect Monster', 'Fiend', 'DARK', 4, 1700, NULL, '①：这张卡被效果从手卡丢弃去墓地的场合发动。从卡组把1张「暗黑界」卡加入手卡。被对方的效果丢弃的场合，发动时可以以对方墓地1只怪兽为对象。那个场合，再让以下效果适用。 ●作为对象的怪兽在自己场上守备表示特殊召唤。'),
(35448319, 'Snyffus', '除草兽', '除草獣', 'Tuner Monster', 'Beast', 'EARTH', 1, 100, 100, '1回合1次，可以把自己场上存在的1只植物族怪兽解放，选择对方场上表侧表示存在的1张卡破坏。此外，这张卡在墓地存在，场上存在的植物族怪兽被破坏时，这张卡可以从墓地特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合从游戏中除外。'),
(26381750, 'Soaring Eagle Above the Searing Land', '红莲地带的飞鹰', '紅蓮地帯を飛ぶ鷹', 'Tuner Monster', 'Winged Beast', 'FIRE', 1, 100, NULL, '这张卡被同调怪兽的同调召唤使用送去墓地的场合自己墓地有名字带有「熔岩」的怪兽3种类以上存在的场合，这张卡可以在自己场上特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合从游戏中除外。'),
(86318356, 'Sogen', '草原', '草原', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '全部战士族·兽战士族的怪兽攻击力·守备力上升200。'),
(60246171, 'Soitsu', '他者', 'ソイツ', 'Normal Monster', 'Fairy', 'WIND', 3, NULL, NULL, '虽然时常摆着一副相当无助的姿态，却总让人觉得其实还隐藏着什么惊人潜在能力的样子。'),
(19739265, 'Sol and Luna', '日与月', 'サン・アンド・ムーン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己以及对方场上的怪兽各1只为对象才能发动。那些怪兽各受那表示形式的以下效果适用。 ●表侧表示：变成里侧守备表示。 ●里侧表示：变成表侧守备表示。'),
(45985838, 'Solar Flare Dragon', '日珥龙', 'プロミネンス・ドラゴン', 'Effect Monster', 'Pyro', 'FIRE', 4, 1500, 1000, '若自己场上有除这张卡以外的炎族怪兽存在，则这张卡不能被攻击。在自己的每回合的结束阶段，给与对方基本分500分的伤害。'),
(44472639, 'Solar Ray', '太阳射线', 'ソーラーレイ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对对方造成数值与自己场上存在的光属性怪兽数量×600点等同的伤害。'),
(691925, 'Solar Recharge', '太阳能交换', 'ソーラー・エクスチェンジ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从手卡丢弃1只「光道」怪兽才能发动。自己抽2张。那之后，从自己卡组上面把2张卡送去墓地。'),
(33911264, 'Solar Wind Jammer', '太阳风帆船', '太陽風帆船', 'Effect Monster', 'Machine', 'LIGHT', 5, 800, 2400, '自己场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。这个方法特殊召唤的这张卡的原本的攻击力·守备力变成一半。此外，每次自己的准备阶段这张卡的等级上升1星。「太阳风帆船」在场上只能有1只表侧表示存在。'),
(7805147, 'Soldier Dragons', '兵队龙', '兵隊竜', 'Effect Monster', 'Dragon', 'EARTH', 2, 700, 800, '①：1回合1次，对方把魔法·陷阱·怪兽的效果发动时才能发动。从卡组把1只2星以下的龙族怪兽特殊召唤。'),
(33318980, 'Soldier Gaia the Fierce Knight', '暗黑骑士盖亚士兵', '暗黒騎士ガイアソルジャー', 'Effect Monster', 'Warrior', 'DARK', 8, 2600, 2100, '这个卡名的①②③的效果1回合各能使用1次。 ①：把自己场上1只龙族融合怪兽解放才能发动。这张卡从手卡特殊召唤。这个效果在对方回合也能发动。 ②：这张卡特殊召唤成功的场合，以场上1只攻击表示怪兽为对象才能发动。那只怪兽变成守备表示。 ③：把这张卡解放才能发动。从卡组把「暗黑骑士 盖亚战士」以外的1只7星以上的战士族怪兽加入手卡。'),
(16308000, 'Solemn Authority', '神之威光', '神の威光', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只名字带有「极神」的怪兽发动。只要这张卡在场上存在，双方玩家不能把选择的怪兽作为卡的效果的对象。发动后第2次的自己的准备阶段时这张卡送去墓地。'),
(41420027, 'Solemn Judgment', '神之宣告', '神の宣告', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：可以把基本分支付一半把以下效果发动。 ●魔法·陷阱卡发动时才能发动。那个发动无效并破坏。 ●自己或对方把怪兽召唤·反转召唤·特殊召唤之际才能发动。那个无效，那些怪兽破坏。'),
(78114463, 'Solemn Report', NULL, NULL, 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, NULL),
(92512625, 'Solemn Scolding', '神之忠告', '神の忠告', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：自己的魔法与陷阱区域盖放的卡只有这张卡的场合，支付3000基本分才能发动。 ●怪兽的效果·魔法·陷阱卡发动时才能发动。那个发动无效并破坏。 ●自己或者对方把怪兽召唤·反转召唤·特殊召唤之际才能发动。那个无效，那些怪兽破坏。'),
(40605147, 'Solemn Strike', '神之通告', '神の通告', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：可以支付1500基本分把以下效果发动。 ●怪兽的效果发动时才能发动。那个发动无效并破坏。 ●自己或对方把怪兽特殊召唤之际才能发动。那次特殊召唤无效，那些怪兽破坏。'),
(84749824, 'Solemn Warning', '神之警告', '神の警告', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：可以支付2000基本分把以下效果发动。 ●包含把怪兽特殊召唤效果的怪兽的效果·魔法·陷阱卡发动时才能发动。那个发动无效并破坏。 ●自己或对方把怪兽召唤·反转召唤·特殊召唤之际才能发动。那个无效，那些怪兽破坏。'),
(35346968, 'Solemn Wishes', '神之恩惠', '神の恵み', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，每次自己抽卡，自己回复500基本分。'),
(27870337, 'Solfachord Elegance', '音服和弦・优雅', 'ドレミコード・エレガンス', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以从以下效果选择1个发动。 ●从卡组把1只「七音服」灵摆怪兽在自己的灵摆区域放置。 ●从手卡把1只「七音服」灵摆怪兽表侧加入额外卡组。那之后，从卡组把灵摆刻度是奇数和偶数的「七音服」灵摆怪兽各1只在自己的灵摆区域放置。 ●从自己的灵摆区域把灵摆刻度是奇数和偶数的卡各1张表侧加入额外卡组，自己抽2张。'),
(92043888, 'Solfachord Formal', '音服和弦・端庄', 'ドレミコード・フォーマル', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己的灵摆区域有「七音服」卡存在，对方把怪兽的效果·魔法·陷阱卡发动时才能发动。从自己的额外卡组让1只表侧表示的灵摆怪兽回到卡组。那之后，以下效果适用。 ●自己场上的灵摆怪兽不受那个对方的效果影响。 ●自己的灵摆区域的卡不会被那个对方的效果破坏。 ●自己的灵摆区域的卡不能用那个对方的效果除外。'),
(93481594, 'Solfachord Happiness', '音服和弦・幸福多重奏', '幸せの多重奏', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：可以从以下效果选择1个发动（这个卡名的以下效果1回合各能选择1次）。 ●选自己1张手卡丢弃，从卡组把2只灵摆刻度不同的「七音服」灵摆怪兽加入手卡。那之后，可以把最多有对方场上的怪兽数量＋1只的「七音服」灵摆怪兽从手卡特殊召唤。 ●这个回合，自己在通常的灵摆召唤外加上只有1次，自己主要阶段可以把「七音服」怪兽灵摆召唤。 ●自己的灵摆区域2张「七音服」卡特殊召唤。'),
(29650040, 'Solfachord Harmonia', '音服和弦・和音', 'ドレミコード・ハルモニア', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：可以从以下效果选择1个发动。「七音服的调和」的以下效果1回合各能选择1次。 ●从自己的额外卡组把1只表侧表示的「七音服」灵摆怪兽加入手卡。 ●选自己的灵摆区域1张「七音服」卡。这个回合，那个灵摆刻度上升那张卡的等级数值。 ●自己场上的「七音服」灵摆怪兽卡的灵摆刻度是奇数3种类以上或者偶数3种类以上的场合，选对方场上1张卡破坏。'),
(56058749, 'Solfachord Musica', '音服和弦・音乐', 'ドレミコード・ムジカ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以从自己场上的「七音服」灵摆怪兽卡的灵摆刻度的以下效果选择1个发动。 ●奇数：从自己的额外卡组把1只灵摆刻度是奇数的表侧表示的「七音服」灵摆怪兽特殊召唤。 ●偶数：从自己的额外卡组把1只灵摆刻度是偶数的表侧表示的「七音服」灵摆怪兽特殊召唤。 ●奇数和偶数：以对方场上1张卡为对象才能发动。那张卡破坏。'),
(11688916, 'Solfachord Primoa', '音服和弦・普莉莫娅', 'ドレミコード・プリモア', 'Pendulum Effect Monster', 'Fairy', 'EARTH', 1, NULL, 400, '这个卡名的①③的怪兽效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把「七音服·普莉莫娅」以外的1张「七音服」卡加入手卡。 ②：只要自己的灵摆区域有灵摆刻度是奇数和偶数的「七音服」卡各存在，自己发动的「七音服」卡的效果不会被无效化。 ③：自己把「七音服」怪兽连接召唤的场合才能发动。从自己的额外卡组（表侧）·墓地把1张「七音服」卡加入手卡。'),
(53265336, 'Solfachord Scale', '音服和弦・音阶', 'ドレミコード・スケール', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上的「七音服」灵摆怪兽卡种类的以下效果各能适用。 ●3种类以上：选自己的灵摆区域1张卡回到持有者手卡，从自己的额外卡组选1只表侧表示的「七音服」灵摆怪兽在自己的灵摆区域放置。 ●5种类以上：从手卡把1只「七音服」灵摆怪兽特殊召唤。 ●7种类以上：对方场上的表侧表示的卡全部破坏。'),
(84693918, 'Solfachord Solfegia', '音服和弦・索露菲基娅', 'ドレミコード・ソルフェージア', 'Pendulum Effect Monster', 'Fairy', 'LIGHT', 2, 400, 400, '这个卡名的①②的怪兽效果1回合各能使用1次。 ①：自己场上的怪兽不存在的场合或者只有「七音服」怪兽的场合才能发动。这张卡从手卡特殊召唤。 ②：自己主要阶段才能发动（也能把这张卡解放来发动）。从手卡把「七音服·索尔费吉娅」以外的1只「七音服」怪兽特殊召唤。把这张卡解放发动的场合，也能从自己的额外卡组（表侧）·墓地选特殊召唤的怪兽。'),
(56510115, 'Solfachord Symphony', '音服和弦・交响曲', 'ドレミコード・シンフォニア', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己的额外卡组的表侧表示的「七音服」灵摆怪兽种类的以下效果适用。 ●3种类以上：这个回合，自己场上的「七音服」灵摆怪兽的攻击力上升自身的灵摆刻度×300。 ●5种类以上：可以选对方场上1张卡破坏。自己的灵摆区域有奇数的灵摆刻度存在的场合，再让自己从卡组抽1张。 ●7种类以上：可以从额外卡组把1只「大钢琴之七音服」怪兽特殊召唤。'),
(86780027, 'Solidarity', '一族之团结', '一族の結束', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：自己墓地的全部怪兽的原本种族相同的场合，自己场上的那个种族的怪兽的攻击力上升800。'),
(28966434, 'Solitaire Magician', '单宝石小魔女', 'ソリテア・マジカル', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1600, 1300, '选择自己场上表侧表示存在的1只名字带有「命运女郎」的怪兽和场上表侧表示存在的1只怪兽发动。选择的名字带有「命运女郎」的怪兽的等级下降3星，选择的另1只怪兽破坏。这个效果1回合只能使用1次。'),
(93377803, 'Solitary Sword of Poison', '孤毒之剑', '孤毒の剣', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '自己场上的怪兽才能装备。 ①：「孤毒之剑」在自己场上只能有1张表侧表示存在。 ②：装备怪兽的原本的攻击力·守备力只在和对方怪兽进行战斗的伤害计算时变成2倍。 ③：自己场上有装备怪兽以外的怪兽存在的场合这张卡送去墓地。'),
(84794011, 'Solitude', '孤寂', 'ソリテュード', 'Normal Monster', 'Beast-Warrior', 'EARTH', 3, 1050, 1000, '下半身是鹿，持有吸收灵魂的大镰刀的兽战士。'),
(14763299, 'Solo the Melodious Songstress', '幻奏的歌姬 索萝', '幻奏の歌姫ソロ', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1600, 1000, '①：对方场上有怪兽存在，自己场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡被战斗破坏送去墓地时才能发动。从卡组把「幻奏的歌姬 索萝」以外的1只「幻奏」怪兽特殊召唤。'),
(23471572, 'Solomon''s Lawbook', '所罗门的律法书', 'ソロモンの律法書', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '下次的自己的准备阶段跳过。'),
(91598270, 'SolSolfachord Gracia', '索音服和弦・格蕾西娅', 'ソドレミコード・グレーシア', 'Pendulum Effect Monster', 'Fairy', 'WATER', 5, 2100, 1400, '这个卡名的①的怪兽效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把1张「七音服」魔法·陷阱卡加入手卡。 ②：自己的灵摆区域有偶数的灵摆刻度存在，自己的「七音服」灵摆怪兽攻击的场合，对方直到伤害步骤结束时怪兽的效果不能发动。'),
(38406364, 'Some Summer Summoner', '常夏的雷鸣大人', '常夏のカミナリサマー', 'Link Monster', 'Thunder', 'LIGHT', NULL, 1600, NULL, '雷族怪兽2只 ①：对方回合1次，丢弃1张手卡，以连接怪兽以外的自己墓地1只雷族怪兽为对象才能发动。那只怪兽在作为这张卡所连接区的自己场上特殊召唤。'),
(76990617, 'Sonata the Melodious Diva', '幻奏音女 索娜塔', '幻奏の音女ソナタ', 'Effect Monster', 'Fairy', 'LIGHT', 3, 1200, 1000, '①：自己场上有「幻奏」怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：只要特殊召唤的这张卡在怪兽区域存在，自己场上的天使族怪兽的攻击力·守备力上升500。'),
(58053438, 'Songs of the Dominators', '列王诗篇', '列王詩篇', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。自己墓地没有怪兽存在的场合，这张卡的发动从手卡也能用。 ①：对方把场上的怪兽的效果发动时才能发动。那个效果无效。自己墓地有陷阱卡存在的场合，可以再从卡组把1张「统王」卡加入手卡。这张卡从手卡发动的场合，发动后，直到下个回合的结束时自己不能把手卡·墓地·除外状态的怪兽的效果发动。'),
(57617178, 'Sonic Bird', '音速鸟', 'ソニックバード', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1400, 1000, '①：这张卡召唤·反转召唤成功时才能发动。从卡组把1张仪式魔法卡加入手卡。'),
(93211810, 'Sonic Boom', '超音速波', '超音速波', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己回合选择场上1只名字带有「幻兽机」的怪兽才能发动。选择的怪兽在这个回合，攻击力变成原本攻击力的2倍，不受这张卡以外的魔法·陷阱卡的效果影响，向守备表示怪兽攻击时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。那之后，这个回合的结束阶段时自己场上的机械族怪兽全部破坏。这张卡发动的回合，选择的怪兽以外的怪兽不能攻击。'),
(36472900, 'Sonic Chick', '小走鹃', 'ロードランナー', 'Effect Monster', 'Winged Beast', 'EARTH', 1, 300, 300, '①：这张卡不会被和攻击力1900以上的怪兽的战斗破坏。'),
(84696266, 'Sonic Duck', '音速鸭', '音速ダック', 'Normal Monster', 'Winged Beast', 'WIND', 3, 1700, 700, '可以以音速步行的鸭子。由于不能适应其惊人的速度而经常失控。'),
(84550200, 'Sonic Jammer', '声波干扰虫', 'ソニックジャマー', 'Flip Effect Monster', 'Machine', 'WIND', 2, 350, 650, '反转：到下一个结束阶段终了时为止，对方不能发动魔法卡。'),
(38942059, 'Sonic Maid', '音女', '音女', 'Normal Monster', 'Warrior', 'EARTH', 3, 1200, 900, '擅长操纵声音的少女，能使音符变成镰刀攻击敌人。'),
(40384720, 'Sonic Shooter', '音速射手', 'ソニック・シューター', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1300, 600, '对方的魔法·陷阱卡区域没有卡存在的场合，这张卡可以直接攻击对方玩家。这个时候，给与对方玩家的战斗伤害变成这张卡的原本攻击力的数值。'),
(93138457, 'Sonic Stun', '战斗无力化音速', 'バトル・スタン・ソニック', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方怪兽的攻击宣言时才能发动。那次攻击无效。那之后，可以从手卡·卡组把1只「科技属」怪兽或者4星以下的调整特殊召唤。'),
(17888577, 'Sonic Tracker', '追逐音速者', '音速を追う者', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「跨音速鸟」的降临必需。这个卡名的②的效果1回合只能使用1次。 ①：等级合计直到4以上的自己的手卡·场上的怪兽解放，从手卡把「跨音速鸟」仪式召唤。这个效果特殊召唤的怪兽的等级变成那次仪式召唤使用的怪兽的等级合计的等级。 ②：把墓地的这张卡除外，以自己场上1只仪式怪兽为对象才能发动。种族或者属性和那只怪兽相同的1只仪式怪兽从卡组送去墓地。'),
(17932494, 'Sonic Warrior', '音速战士', 'ソニック・ウォリアー', 'Effect Monster', 'Warrior', 'WIND', 2, 1000, NULL, '①：这张卡被送去墓地的场合发动。自己场上的全部2星以下的怪兽的攻击力上升500。'),
(4335427, 'Sophia, Goddess of Rebirth', '创星神 索菲娅', '創星神 sophia', 'Effect Monster', 'Fairy', 'DARK', 11, 3600, 3400, '这张卡不能通常召唤。把自己·对方场上表侧表示存在的仪式·融合·同调·超量怪兽各1只从游戏中除外的场合才能特殊召唤。这张卡的特殊召唤不会被无效化。这张卡特殊召唤成功时，这张卡以外的双方的手卡·场上·墓地的卡全部从游戏中除外。不能对应这个效果的发动让魔法·陷阱·效果怪兽的效果发动。'),
(62895219, 'Soprano the Melodious Songstress', '幻奏歌姬 索普拉诺', '幻奏の歌姫ソプラノ', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1400, 1400, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡特殊召唤时，以「幻奏的歌姬 索普拉诺」以外的自己墓地1只「幻奏」怪兽为对象才能发动。那只怪兽加入手卡。 ②：1回合1次，自己主要阶段才能发动。包含这张卡的自己场上的怪兽作为融合素材，把1只「幻奏」融合怪兽融合召唤。'),
(88619463, 'Sorcerer of Dark Magic', '黑魔法神官', '黒の魔法神官', 'Effect Monster', 'Spellcaster', 'DARK', 9, 3200, 2800, '这张卡不能通常召唤。把自己场上2只6星以上的魔法师族怪兽解放的场合才能特殊召唤。 ①：陷阱卡发动时才能发动。这张卡在场上表侧表示存在的场合，那个发动无效并破坏。'),
(39767432, 'Sorcerer of Sebek', '索贝克的魔导士', 'セベクの魔導士', 'Link Monster', 'Aqua', 'WATER', NULL, 2000, NULL, '效果怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡或者这张卡所连接区的自己怪兽给与对方战斗伤害时才能发动。自己基本分回复那个数值。 ②：自己或对方的基本分回复的场合才能发动（伤害步骤也能发动）。双方受到1000伤害。'),
(49218300, 'Sorcerer of the Doomed', '死亡巫师', 'デス・ソーサラー', 'Normal Monster', 'Spellcaster', 'DARK', 4, 1450, 1200, '擅长死亡魔法的魔法师，和黑暗订下了契约。'),
(81231742, 'Sorcerous Spell Wall', '破邪之魔法壁', '破邪の魔法壁', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：自己场上的怪兽在自己回合内攻击力上升300，对方回合内守备力上升300。'),
(36405256, 'Sorciere de Fleur', '鲜花之魔女', '時花の魔女－フルール・ド・ソルシエール', 'Effect Monster', 'Spellcaster', 'DARK', 8, 2900, NULL, '这个卡名的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合，以对方墓地1只怪兽为对象发动。那只怪兽在自己场上特殊召唤。这个效果特殊召唤的怪兽不能向对方直接攻击，这个回合的结束阶段破坏。'),
(92487128, 'Sosei Ryu-Ge Mistva', '创星龙华－光轮巴王', '創星竜華－光巴', 'Pendulum Effect Ritual Monster', 'Dragon', 'LIGHT', 10, 3500, 2500, '「创星龙华-光巴」降临 这张卡用这张卡的效果才能特殊召唤。自己对「创星龙华-光巴」1回合只能有1次特殊召唤。 ①：这张卡在额外卡组存在的状态，场上的怪兽被战斗·效果破坏的场合才能发动。自己场上1只10星「龙华」怪兽解放，这张卡当作仪式召唤作特殊召唤。那之后，以下可以适用。 ●自己场上最多2张卡破坏，把最多有那个数量的「龙华」永续魔法卡从卡组到自己场上表侧表示放置。'),
(68073522, 'Soul Absorption', '魂吸收', '魂吸収', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '将卡从游戏中除外时，每除外1张，这张卡的控制者自己回复500基本分。'),
(6909330, 'Soul Binding Gate', '魂缚门', '魂縛門', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '自己场上盖放的魔法·陷阱卡被效果破坏的回合，自己场上没有怪兽存在的场合才能把这张卡发动。 ①：自己·对方的主要阶段，自己墓地有「Z-ONE」存在，只让持有比自己基本分数值低的攻击力的怪兽1只召唤·反转召唤·特殊召唤的场合发动。那只怪兽破坏，自己受到800伤害。那之后，给与对方800伤害。'),
(54447022, 'Soul Charge', '灵魂补充', 'ソウル・チャージ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己不能进行战斗阶段。 ①：以自己墓地的怪兽任意数量为对象才能发动。那些怪兽特殊召唤，自己失去这个效果特殊召唤的怪兽数量×1000基本分。'),
(5253985, 'Soul Crossing', '交错之魂', '交差する魂', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己·对方的主要阶段才能发动。把1只幻神兽族怪兽上级召唤。那个时候，也能作为自己场上的怪兽的代替而把对方场上的怪兽解放。把对方场上的怪兽解放作上级召唤的场合，以下效果适用。 ●这张卡的发动后，直到下个回合的结束时自己1回合只能有1次把幻神兽族怪兽以外的魔法·陷阱·怪兽的效果发动。'),
(76297408, 'Soul Demolition', '魂粉碎', '魂粉砕', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '支付500分，互相选择对方墓地的1张怪兽卡。选择的卡从游戏中除外。这个效果在自己的场上有恶魔族存在的场合才能发动。'),
(51670553, 'Soul Devouring Bamboo Sword', '吸魂的竹光', '魂を吸う竹光', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '选择名字带有「竹光」的装备魔法卡所装备给的1只怪兽才能发动。选择的怪兽给与对方基本分战斗伤害的场合，下次的对方的抽卡阶段跳过。这张卡在发动后第2次的自己的准备阶段时破坏。'),
(73599290, 'Soul Drain', '灵魂抽取', 'ソウルドレイン', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '支付1000基本分才能发动。只要这张卡在场上存在，从游戏中除外的怪兽的效果以及墓地存在的怪兽的效果不能发动。'),
(55735315, 'Soul Drain Dragon', '魂食神龙 吸灵龙', '魂食神龍ドレイン・ドラゴン', 'Effect Monster', 'Dragon', 'LIGHT', 8, 4000, NULL, '这张卡不能通常召唤。自己的龙族超量怪兽的效果才能特殊召唤。这张卡特殊召唤成功时，自己基本分比对方少的场合，这张卡的攻击力上升那个相差数值，这个回合对方玩家受到的全部伤害变成0。此外，这张卡不能向对方玩家直接攻击。'),
(79339613, 'Soul Energy MAX!!!', '灵魂能量最大级！！', 'ソウルエナジーMAX！！', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有原本属性是神属性的「欧贝利斯克之巨神兵」存在的场合，把自己场上2只其他的表侧表示怪兽解放才能发动。对方场上的怪兽全部破坏，给与对方4000伤害。 ②：自己·对方的主要阶段以及战斗阶段，把墓地的这张卡除外才能发动。从自己的卡组·墓地选1只「欧贝利斯克之巨神兵」加入手卡。那之后，可以把1只「欧贝利斯克之巨神兵」召唤。'),
(68005187, 'Soul Exchange', '灵魂交换', 'クロス・ソウル', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡发动的回合，自己不能进行战斗阶段。 ①：以对方场上1只怪兽为对象才能发动。这个回合，自己把怪兽解放的场合，必须作为自己场上1只怪兽的代替而把作为对象的对方怪兽解放。'),
(69533836, 'Soul Fist', '刻魂之右', '魂を刻む右', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '自己场上的龙族同调怪兽才能装备。 ①：这张卡装备的「红莲魔龙」不受对方发动的效果影响。 ②：1回合1次，自己主要阶段才能发动。对方场上的全部怪兽的攻击力变成和装备怪兽相同。 ③：1回合1次，装备怪兽进行战斗的攻击宣言时，以对方墓地1只怪兽为对象才能发动。那只怪兽除外。装备怪兽的攻击力直到回合结束时上升除外的怪兽的攻击力数值。'),
(72869010, 'Soul Hunter', '狩魂魔人', 'ソウル・ハンター', 'Fusion Monster', 'Fiend', 'DARK', 6, 2200, 1800, '「神灯魔人」＋「来自异次元的侵略者」'),
(87844926, 'Soul Levy', '灵魂召集', 'ソウル・レヴィ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：「灵魂召集」在自己场上只能有1张表侧表示存在。 ②：只要这张卡在魔法与陷阱区域存在，每次对方对怪兽的特殊召唤成功，从对方卡组上面把3张卡送去墓地。'),
(95026693, 'Soul of Fire', '火焰之魂', 'ファイヤー・ソウル', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '对方玩家抽1张卡。从自己卡组选择1只炎族怪兽从游戏中除外。给与对方基本分除外怪兽的攻击力一半数值的伤害。这张卡发动的场合，这个回合自己不能攻击宣言。'),
(73129314, 'Soul of Gaia the Fierce Knight', '寄托于魂的暗黑骑士盖亚', '魂宿りし暗黒騎士ガイア', 'Effect Monster', 'Warrior', 'EARTH', 6, 2300, 2100, '这个卡名在规则上也当作「千年」卡使用。这个卡名的③的效果1回合只能使用1次。 ①：场上有5星以上的怪兽卡存在的场合，这张卡可以不用解放作召唤。 ②：只要这张卡在怪兽区域存在，那个期间对方攻击表示召唤·特殊召唤的怪兽的等级上升7星。 ③：对方把怪兽的效果发动时，把除这张卡外的自己场上1张5星以上的表侧表示的怪兽卡送去墓地才能发动。那个发动无效并破坏。'),
(77527210, 'Soul of Purity and Light', '神圣之魂', '神聖なる魂', 'Effect Monster', 'Fairy', 'LIGHT', 6, 2000, 1800, '这张卡不能通常召唤。从自己墓地把2只光属性怪兽除外的场合可以特殊召唤。 ①：只要这张卡在怪兽区域存在，对方场上的怪兽的攻击力在对方战斗阶段内下降300。'),
(91895091, 'Soul of Silvermountain', '银岭之巨神', '銀嶺の巨神', 'XYZ Monster', 'Rock', 'EARTH', 3, 1800, 2200, '地属性3星怪兽×2 1回合1次，把这张卡1个超量素材取除，选择对方的魔法与陷阱卡区域盖放的1张卡才能发动。选择的卡只要这张卡在场上表侧表示存在不能发动。此外，持有超量素材的这张卡战斗破坏对方怪兽的场合，可以选择自己墓地1只地属性怪兽表侧守备表示特殊召唤。'),
(47852924, 'Soul of the Pure', '天使的鲜血', '天使の生き血', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己回复800点的基本分。'),
(76840111, 'Soul of the Supreme Celestial King', '霸王天龙之魂', '覇王天龍の魂', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把自己场上1只原本攻击力是2500的魔法师族灵摆怪兽解放才能发动。自己的手卡·卡组·额外卡组·场上·墓地的怪兽作为融合素材除外，把1只「霸王龙 扎克」融合召唤。除自己的除外状态的「灵摆龙」「超量龙」「同调龙」「融合龙」怪兽各存在的场合外，这个效果特殊召唤的怪兽的效果无效化。'),
(92428405, 'Soul of the Supreme King', '霸王龙之魂', '覇王龍の魂', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把基本分支付一半才能发动。把1只「霸王龙 扎克」从额外卡组无视召唤条件并效果无效特殊召唤。那只怪兽在下个回合的结束阶段回到持有者的额外卡组。 ②：对方把魔法卡的效果发动时，把墓地的这张卡和自己场上1只「霸王龙 扎克」除外才能发动。从自己的手卡·卡组·额外卡组·墓地选「灵摆龙」「超量龙」「同调龙」「融合龙」怪兽各最多1只特殊召唤。'),
(34884015, 'Soul Pendulum', '魂之灵摆', '魂のペンデュラム', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：以自己的灵摆区域2张卡为对象才能发动。作为对象的卡的灵摆刻度各自上升或下降1（最少到1）。 ②：每次自己的灵摆怪兽灵摆召唤给这张卡放置1个指示物。 ③：场上的灵摆怪兽的攻击力上升这张卡的指示物数量×300。 ④：把这张卡3个指示物取除才能发动。这个回合，自己在通常的灵摆召唤外加上只有1次，自己主要阶段可以把怪兽灵摆召唤。'),
(5758500, 'Soul Release', '魂之解放', '魂の解放', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己·对方的墓地的卡合计最多5张为对象才能发动。那些卡除外。'),
(62991792, 'Soul Resonator', '魂灵共鸣者', 'ソウル・リゾネーター', 'Tuner Monster', 'Fiend', 'FIRE', 3, 500, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。除「灵魂共鸣者」外的1只4星以下的恶魔族怪兽从卡组加入手卡。这个效果的发动后，直到回合结束时自己不是暗属性同调怪兽不能从额外卡组特殊召唤。 ②：自己场上有着「红莲魔龙」或者有那个卡名记述的同调怪兽存在，自己场上的卡被效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(92924317, 'Soul Resurrection', '苏生之魂', '蘇りし魂', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：以自己墓地1只通常怪兽为对象才能把这张卡发动。那只怪兽守备表示特殊召唤。这张卡从场上离开时那只怪兽破坏。那只怪兽破坏时这张卡破坏。'),
(78864369, 'Soul Reversal', '还魂', 'リバースソウル', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '将自己墓地里的1张反转效果怪兽卡弹回卡组最上面。'),
(37383714, 'Soul Rope', '魂之纲', '魂の綱', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上的怪兽被效果破坏送去墓地时，支付1000基本分才能发动。从卡组把1只4星怪兽特殊召唤。'),
(12061457, 'Soul Scissors', '灵魂剪刀', 'ソウル・シザー', 'Effect Monster', 'Fiend', 'DARK', 2, 550, 350, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在墓地存在的状态，场上的怪兽被战斗·效果破坏送去墓地的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：这张卡从墓地的特殊召唤成功的场合，以对方场上1只怪兽为对象才能发动。那只怪兽破坏。'),
(23020408, 'Soul Servant', '魂之侍从', '魂のしもべ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：从自己的手卡·卡组·墓地选除「魂之仆人」外的1只「黑魔术师」或「黑魔术少女」或者1张有那其中任意种的卡名记述的卡在卡组最上面放置。 ②：自己主要阶段把墓地的这张卡除外才能发动。自己抽出双方的场上·墓地的「守护神官」怪兽、「黑魔术师」、「黑魔术少女」种类的数量。'),
(36376145, 'Soul Strike', '魂之一击', '魂の一撃', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己基本分是4000以下的场合，自己场上的怪兽和对方怪兽进行战斗的攻击宣言时把基本分支付一半，选择自己场上1只怪兽才能发动。选择的怪兽的攻击力直到对方的结束阶段时上升自己基本分比4000低的数值。「魂之一击」在1回合只能发动1张。'),
(81510157, 'Soul Taker', '灵魂捕获者', 'ソウルテイカー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以对方场上1只表侧表示怪兽为对象才能发动。那只对方的表侧表示怪兽破坏。那之后，对方回复1000基本分。'),
(15734813, 'Soul Tiger', '魂虎', '魂虎', 'Normal Monster', 'Beast', 'EARTH', 4, NULL, 2100, '据说是贪婪人类灵魂的可怕老虎的邪恶灵魂。如果可以的话，任谁都不想遇见的怪兽。'),
(82324106, 'Soul Token', '对极限的冲动', '極限への衝動', 'Token', 'Fiend', NULL, NULL, NULL, NULL, NULL),
(88197162, 'Soul Transition', '魂之转身', '魂の転身', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '「魂之转身」在1回合只能发动1张，这张卡发动的回合，自己不能把怪兽特殊召唤。 ①：自己场上没有特殊召唤的怪兽存在的场合，把自己场上1只通常召唤的表侧表示的4星怪兽解放才能发动。自己从卡组抽2张。'),
(69389481, 'Soul Union', '魂之团结－灵魂联合', '魂の結束－ソウル・ユニオン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以场上1只表侧表示怪兽和自己墓地1只「元素英雄」怪兽为对象才能发动。作为对象的场上的怪兽的攻击力直到回合结束时上升作为对象的墓地的怪兽的攻击力数值。自己的场上或墓地有「元素英雄」通常怪兽存在的场合，可以再让以下效果适用。 ●自己墓地的怪兽作为融合素材除外，把1只「元素英雄」融合怪兽融合召唤。'),
(90506641, 'Soul Unseal', '魂之开封', '魂の開封', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方场上有怪兽存在，自己场上有通常怪兽存在的场合才能发动。从卡组选5只通常怪兽。那之内的1只加入手卡，剩下的卡除外。'),
(63012333, 'Soul-Absorbing Bone Tower', '吸食精气的骨塔', '精気を吸う骨の塔', 'Effect Monster', 'Zombie', 'DARK', 3, 400, 1500, '若自己场上有除这张卡以外的不死族怪兽存在，则这张卡不能被攻击。每当不死族怪兽特殊召唤成功时，将对方卡组最上面2张卡送去墓地。'),
(31242786, 'Souleater', '食魂鱼', '魂喰らい', 'Normal Monster', 'Fish', 'EARTH', 4, 1200, NULL, '一切都是迷的超生命体。'),
(44335251, 'Souleating Oviraptor', '食魂窃蛋龙', '魂喰いオヴィラプター', 'Effect Monster', 'Dinosaur', 'DARK', 4, 1800, 500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组选1只恐龙族怪兽加入手卡或送去墓地。 ②：以这张卡以外的场上1只4星以下的恐龙族怪兽为对象才能发动。那只怪兽破坏。那之后，从自己墓地选1只恐龙族怪兽守备表示特殊召唤。'),
(24514503, 'Soulicer Crystal', '冻结心灵的雪晶怪', '心を凍らせるスノークリスタル', 'Effect Monster', 'Aqua', 'LIGHT', 6, 300, 1900, '这个卡名的①③的效果1回合各能使用1次。 ①：这张卡在手卡存在，自己场上的怪兽数量比对方场上的怪兽少2只以上的场合才能发动。这张卡特殊召唤。 ②：场上的这张卡不会被效果破坏。 ③：以对方场上1只效果怪兽为对象才能发动。那只怪兽的效果无效。'),
(4920010, 'Souls of the Forgotten', '怨念集合体', '怨念集合体', 'Normal Monster', 'Fiend', 'DARK', 2, 900, 200, '怀恨而死的人的意识集成的恶灵，袭击人的意识在不断的变大。'),
(81665333, 'Sound the Retreat!', '撤收命令', '撤収命令', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上存在的怪兽全部回到持有者手卡。'),
(42314669, 'Soundproofed', '完全防音壁', '完全防音壁', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上没有同调怪兽表侧表示存在的场合，主要阶段1的开始时才能发动。直到下次的对方的结束阶段时，双方不能把同调怪兽特殊召唤。'),
(65107325, 'Sour Scheduling - Red Vinegar Vamoose', '红醋道口', '赤酢の踏切', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：「赤醋的道口」在自己场上只能有1张表侧表示存在。 ②：和盖放的这张卡相同纵列有对方的卡存在的场合才能把这张卡发动。和这张卡相同纵列的除这张卡以外的卡全部回到持有者手卡。 ③：只要这张卡在魔法与陷阱区域存在，和这张卡相同纵列的没有使用的区域不能使用。'),
(69176131, 'Space Cyclone', '太空旋风', 'スペース・サイクロン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '把场上存在的1个超量素材取除。'),
(92092092, 'Space Dragster', '调星之直线竞速士', '調星のドラッグスター', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：这张卡发动后变成效果怪兽（机械族·调整·炎·1星·攻0/守1800）在怪兽区域特殊召唤。这张卡也当作陷阱卡使用。 ②：只要这张卡的效果特殊召唤的这张卡在怪兽区域存在，这张卡以外的自己场上的调整不会被战斗以及对方的效果破坏。'),
(1539051, 'Space Gift', '空间礼物', 'スペーシア・ギフト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的名字带有「新空间侠」的怪兽每有1种类，从自己卡组抽1张卡。'),
(4914353, 'Space Insulator', '空隙绝缘人', 'スペース・インシュレイター', 'Link Monster', 'Cyberse', 'DARK', NULL, 1200, NULL, '怪兽2只 ①：这张卡所连接区的怪兽的攻击力·守备力下降800。 ②：这张卡在墓地存在，自己场上有电子界族连接怪兽连接召唤时才能发动。这张卡在作为那只怪兽所连接区的自己场上特殊召唤。这个效果特殊召唤的这张卡不能作为连接素材，从场上离开的场合除外。这个效果在这张卡送去墓地的回合不能发动。'),
(36119641, 'Space Mambo', '太空翻车鱼', 'スペースマンボウ', 'Normal Monster', 'Fish', 'WATER', 4, 1700, 1000, '在广大的银河中漂流的宇宙飞船。从外太空-四号的超文明遗迹中被发现的活化石。'),
(47643326, 'Space Omajinai Usagi', '宇宙咒语兔', 'スペース・オマジナイ・ウサギ', 'Normal Tuner Monster', 'Spellcaster', 'LIGHT', 1, NULL, 1500, '从天而降的神秘来访者。将痛觉变换为信号并发送到宇宙，但是其目的至今还不明。 ——痛痛痛痛飞走飞走。'),
(47126872, 'Space-Time Police', '时空警察', 'スペースタイムポリス', 'Effect Monster', 'Psychic', 'WIND', 5, 2300, 1500, '这张卡特殊召唤成功时，选择对方场上表侧表示存在的1张卡从游戏中除外。这张卡从场上离开时，这张卡的效果从游戏中除外的卡在对方场上盖放。'),
(97151365, 'Spacegate', '星之门', 'スターゲート', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '对方怪兽进行战斗的场合，那个伤害步骤结束时给这张卡放置1个门指示物。自己回合的主要阶段时可以把这张卡送去墓地，这张卡放置的门指示物数量以下的等级的1只怪兽从手卡特殊召唤。'),
(39041729, 'Spacetime Transcendence', '时空超越', '時空超越', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从自己墓地把恐龙族怪兽2只以上除外才能发动。从自己的手卡·墓地选持有和除外的怪兽的等级合计相同等级的1只恐龙族怪兽特殊召唤。这个效果特殊召唤的怪兽在这个回合不能攻击。'),
(97362768, 'Spark Blaster', '电光枪', 'スパークガン', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '「元素英雄 电光侠」才能装备。自己的回合的主要阶段时可以把1只表侧表示的怪兽的表示形式改变。这个效果使用3次后，这张卡破坏。'),
(76103675, 'Sparks', '火星', '火の粉', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '给与对方基本分200分伤害。'),
(20644748, 'Spatial Collapse', '宇宙收缩', '宇宙の収縮', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '各自场上存在的卡都在5张以下时这张卡才能发动。双方出场的卡各自不能超过5张。'),
(39984786, 'Spawn Alligator', '产卵短吻鳄', 'スパウン・アリゲーター', 'Effect Monster', 'Reptile', 'WATER', 5, 2200, 1000, '把爬虫类族怪兽解放对这张卡的上级召唤成功的场合，把1只为这张卡的上级召唤而解放的怪兽在那个回合的结束阶段时从墓地往自己场上特殊召唤。'),
(44308317, 'Speaker for the Ice Barriers', '冰结界的依巫', '氷結界の依巫', 'Effect Monster', 'Spellcaster', 'WATER', 4, 1000, 1800, '这个卡名的①③的效果1回合各能使用1次。 ①：自己场上有「冰结界」怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：只要自己场上有其他的「冰结界」怪兽存在，对方场上的守备表示怪兽不能把表示形式变更。 ③：自己场上有「冰结界」怪兽存在的场合，把墓地的这张卡除外才能发动。在自己场上把1只「冰结界衍生物」（水族·水·1星·攻/守0）特殊召唤。'),
(58551308, 'Spear Cretin', '暗黑使魔', 'ダークファミリア', 'Flip Effect Monster', 'Fiend', 'DARK', 2, 500, 500, '反转：这张卡被送去墓地时，双方玩家选择各自墓地存在的1只怪兽，表侧攻击表示或者里侧守备表示特殊召唤。'),
(31553716, 'Spear Dragon', '长枪龙', 'スピア・ドラゴン', 'Effect Monster', 'Dragon', 'WIND', 4, 1900, NULL, '①：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。 ②：这张卡攻击的场合，伤害步骤结束时变成守备表示。'),
(70655556, 'Spear Shark', '鱼叉鲨', 'スピア・シャーク', 'Effect Monster', 'Fish', 'WATER', 4, 1600, 1400, '这张卡召唤成功时，可以让自己场上的全部鱼族·3星怪兽的等级上升1星。这张卡向守备表示怪兽攻击时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。'),
(84569017, 'Spearfish Soldier', '旗鱼战士', 'スピアフィッシュソルジャー', 'Effect Monster', 'Sea Serpent', 'WIND', 4, 1700, 1100, '这张卡的攻击力上升从游戏中除外的自己的鱼族·海龙族·水族怪兽数量×100的数值。'),
(62156277, 'Spearhead of the Ashened City', '灰灭之都的先锋', '灰滅せし都の先懸', 'Effect Monster', 'Pyro', 'DARK', 4, 1700, 100, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：场地区域有「灰灭之都 奥布西地暮」存在的场合，这张卡可以从手卡特殊召唤。 ②：对方场上有攻击力2800以上的怪兽存在的场合，把这张卡解放，以对方场上1张卡为对象才能发动。那张卡回到手卡。'),
(42598242, 'Special Hurricane', '特殊飓风', 'スペシャルハリケーン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '丢弃1张手卡。破坏场上存在的所有特殊召唤的怪兽。'),
(97520701, 'Special Schedule', '临时时刻表', '臨時ダイヤ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己墓地1只攻击力3000以上的机械族怪兽为对象才能发动。那只机械族怪兽守备表示特殊召唤。 ②：盖放的这张卡被送去墓地的场合，以自己墓地1只机械族·10星怪兽为对象才能发动。那只机械族怪兽加入手卡。'),
(12292422, 'Specimen Inspection', '标本阅览', '標本の閲覧', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把手卡1张「化石融合」给对方观看才能发动。从手卡把1只怪兽送去墓地，宣言种族和等级各1个。对方把自身的手卡·卡组确认，有持有宣言的种族·等级的怪兽的场合，那之内的1只送去墓地。'),
(58201062, 'Spectral, Dragon Ruler of Flickers', '光征龙－光谱', '光征竜－スペクトル', 'Effect Monster', 'Dragon', 'LIGHT', 2, 600, 1000, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：把1只龙族或光属性的怪兽和这张卡从手卡丢弃才能发动。从卡组把「光征龙-彩龙」以外的2只「征龙」怪兽加入手卡。 ②：把1只龙族或光属性的怪兽和这张卡从自己墓地除外，以自己墓地1只「极征龙-烛龙」为对象才能发动。那只怪兽特殊召唤。'),
(86174055, 'Speed Bird', '尖嘴鸟', 'スピッド・バード', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1200, 1000, '这张卡被战斗破坏送去墓地时，可以选择自己墓地存在的2只2星的怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(88204302, 'Speed Recovery', '疾行复苏', 'スピードリバース', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地1只「疾行机人」怪兽为对象才能发动。那只怪兽特殊召唤。 ②：把墓地的这张卡除外，以自己墓地1只「疾行机人」怪兽为对象才能发动。那只怪兽加入手卡。这个效果在这张卡送去墓地的回合不能发动。'),
(9365703, 'Speed Warrior', '高速战士', 'スピード・ウォリアー', 'Effect Monster', 'Warrior', 'WIND', 2, 900, 400, '①：这张卡的召唤成功的回合的战斗步骤才能发动。这张卡的攻击力直到战斗阶段结束时变成原本攻击力的2倍。'),
(12950294, 'Speedburst Dragon', '速装龙', 'スピードローダー・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 6, 2400, 600, '这个卡名的①②的效果1回合各能使用1次。 ①：自己受到效果伤害时才能发动。这张卡从手卡特殊召唤。那之后，给与对方为和自己受到的伤害相同数值的伤害，自己基本分回复给与的伤害一半的数值。 ②：这张卡上级召唤成功时才能发动。从卡组把2只「弹丸」怪兽加入手卡（同名卡最多1张）。'),
(36730805, 'Speedlift', '疾行漂移', 'スピードリフト', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：自己场上的怪兽只有调整1只的场合才能发动。从卡组把1只4星以下的「疾行机人」怪兽特殊召唤。在那次特殊召唤成功时双方不能把魔法·陷阱·怪兽的效果发动。'),
(69550259, 'Speedroid Block-n-Roll', '疾行机人 摇滚积木', 'SRブロックンロール', 'Effect Monster', 'Machine', 'WIND', 4, 1000, 1800, '这个卡名的效果1回合只能使用1次。 ①：这张卡作为同调素材送去墓地的场合才能发动。把持有和用这张卡为同调素材的同调怪兽的原本等级相同等级的1只「疾行机人衍生物」（机械族·风·攻/守0）在自己场上特殊召唤。'),
(96945958, 'Speedroid CarTurbo', '疾行机人 歌牌涡轮', 'SRカールターボ', 'Tuner Monster', 'Machine', 'WIND', 3, 800, 1200, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有风属性怪兽存在的场合才能发动。这张卡从手卡特殊召唤。这个效果的发动后，直到回合结束时自己不能把风属性以外的怪兽的效果发动。 ②：从自己墓地把这张卡和1只「疾行机人」怪兽除外才能发动。自己场上的全部风属性怪兽的攻击力直到回合结束时上升800。'),
(66002986, 'Speedroid Clear Wing Wonder', '疾行机人 遥控清透翼惊奇', 'SR／CWW', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以最多有自己场上的风属性同调怪兽的种族种类数量的对方场上的卡为对象才能发动。那些卡破坏。 ②：对方把怪兽特殊召唤的场合，把墓地的这张卡除外，以自己场上1只风属性同调怪兽为对象才能发动。那只怪兽除外。那之后，这个效果除外的怪兽回到场上。'),
(65155517, 'Speedroid Colonel Clackers', '疾行机人 嗒嗒球上校', 'SRクラッカーネル', 'Pendulum Effect Monster', 'Machine', 'WIND', 2, 200, 1800, '这个卡名的①②的怪兽效果1回合各能使用1次。 ①：场上的这张卡被战斗·效果破坏的场合才能发动。从自己的手卡·卡组·墓地把1只「疾行机人 碰碰球上校」当作调整使用特殊召唤。 ②：这张卡在额外卡组表侧存在的状态，自己的「幻透翼」怪兽进行战斗的伤害计算时才能发动。这张卡除外，那只怪兽的攻击力上升700。'),
(59640711, 'Speedroid Den-Den Daiko Duke', '疾行机人 电鼓公爵', 'SR電々大公', 'Tuner Monster', 'Machine', 'WIND', 3, 1000, 1000, '这个卡名的效果1回合只能使用1次。 ①：把墓地的这张卡除外才能发动。从自己的手卡·墓地选「疾行机人 电电大公」以外的1只「疾行机人」调整特殊召唤。'),
(28151978, 'Speedroid Dominobutterfly', '疾行机人 多米诺蝴蝶', 'SRドミノバタフライ', 'Pendulum Tuner Effect Monster', 'Machine', 'WIND', 2, 100, 300, '把这张卡作为同调素材的场合，不是龙族·机械族的风属性怪兽的同调召唤不能使用。从额外卡组特殊召唤的这张卡被同调召唤使用的场合除外。'),
(53054833, 'Speedroid Double Yoyo', '疾行机人 双重溜溜球', 'SRダブルヨーヨー', 'Effect Monster', 'Machine', 'WIND', 4, 1400, 1400, '①：这张卡召唤成功时，以自己墓地1只3星以下的「疾行机人」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(58543073, 'Speedroid Dupligate', '疾行机人分身夺门', 'SRデュプリゲート', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果在决斗中只能使用1次。 ①：从自己墓地把1只风属性怪兽除外，以对方场上1张卡为对象才能发动。那张卡回到持有者手卡。 ②：这张卡在墓地存在的场合，自己主要阶段以自己场上1只「疾行机人」怪兽为对象才能发动。那只怪兽的等级下降1星，这张卡变成通常怪兽（机械族·调整·风·1星·攻/守0）在怪兽区域特殊召唤（不当作陷阱卡使用）。'),
(50482813, 'Speedroid Fuki-Modoshi Piper', '疾行机人 吹笛童子', 'SR吹持童子', 'Tuner Monster', 'Machine', 'WIND', 4, 1000, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。把这张卡以外的自己场上的风属性怪兽数量的卡从自己卡组上面翻开，从那之中选1张加入手卡，剩下的卡用喜欢的顺序回到卡组最下面。 ②：把墓地的这张卡除外，以自己场上1只3星以上的风属性怪兽为对象才能发动。那只怪兽的等级下降2星。'),
(70939418, 'Speedroid Gum Prize', '疾行机人 OMK口香糖', 'SR－OMKガム', 'Tuner Monster', 'Machine', 'WIND', 1, NULL, 800, '①：自己·对方的战斗阶段自己因战斗·效果受到伤害的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡的效果让这张卡特殊召唤成功的战斗阶段才能发动。只用包含这张卡的自己场上的风属性怪兽为同调素材作同调召唤。 ③：这张卡作为同调素材送去墓地的场合才能发动。自己卡组最上面的卡送去墓地，那张卡是「疾行机人」怪兽的场合，这张卡为同调素材的同调怪兽的攻击力上升1000。'),
(23792058, 'Speedroid Hexasaucer', '疾行机人 六角飞盘', 'SRヘキサソーサー', 'Pendulum Effect Monster', 'Machine', 'WIND', 4, 100, 1600, '①：这张卡的战斗发生的战斗伤害由双方玩家承受。 ②：这张卡的战斗发生的双方的战斗伤害变成一半。 ③：这张卡在灵摆区域被破坏的场合才能发动。从自己的额外卡组把1只表侧表示的「疾行机人」灵摆怪兽特殊召唤。'),
(17328157, 'Speedroid Horse Stilts', '疾行机人 竹跷马', 'SRバンブー・ホース', 'Effect Monster', 'Machine', 'WIND', 4, 1100, 1100, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡召唤成功时才能发动。从手卡把1只4星以下的「疾行机人」怪兽特殊召唤。 ②：把墓地的这张卡除外才能发动。从卡组把1只风属性怪兽送去墓地。这个效果在这张卡送去墓地的回合不能发动。'),
(62899696, 'Speedroid Maliciousmagnet', '疾行机人 磁铁恶魔', 'SRアクマグネ', 'Tuner Monster', 'Machine', 'WIND', 1, NULL, NULL, '「疾行机人 磁铁恶魔」的效果1回合只能使用1次。这张卡不用这张卡的效果的同调召唤不能作为同调素材。 ①：这张卡在自己主要阶段召唤·特殊召唤成功的场合，以对方场上1只表侧表示怪兽为对象才能发动。只用那只怪兽和这张卡为素材把1只风属性同调怪兽同调召唤。'),
(96708940, 'Speedroid Marble Machine', '疾行机人 玻璃球机器', 'SRビーダマシーン', 'Pendulum Effect Monster', 'Machine', 'WIND', 2, 200, 100, '这个卡名的怪兽效果1回合只能使用1次。 ①：这张卡召唤成功时才能发动。从卡组把1只「疾行机人」怪兽加入手卡。这个效果的发动后，直到回合结束时自己不是风属性怪兽不能特殊召唤。'),
(16947147, 'Speedroid Menko', '疾行机人 出局画片', 'SRメンコート', 'Effect Monster', 'Machine', 'WIND', 4, 100, 2000, '①：对方怪兽的直接攻击宣言时才能发动。这张卡从手卡攻击表示特殊召唤，对方场上的表侧表示怪兽全部变成守备表示。'),
(89326990, 'Speedroid Ohajikid', '疾行机人 弹子小子', 'SRオハジキッド', 'Effect Monster', 'Machine', 'WIND', 3, 1000, 200, '①：这张卡召唤成功时，以自己或者对方的墓地1只调整为对象才能发动。那只怪兽在自己场上特殊召唤，只用那只怪兽和这张卡为素材把1只风属性同调怪兽同调召唤。'),
(85034450, 'Speedroid Pachingo-Kart', '疾行机人 弹珠机卡丁车', 'SRパチンゴーカート', 'Effect Monster', 'Machine', 'WIND', 4, 1800, 1000, '①：1回合1次，从手卡丢弃1只机械族怪兽，以场上1只怪兽为对象才能发动。那只怪兽破坏。'),
(26420373, 'Speedroid Passinglider', '疾行机人 超车滑翔骑手', 'SRパッシングライダー', 'Pendulum Effect Monster', 'Machine', 'WIND', 5, 2200, 2000, '「疾行机人 超车滑翔骑手」的①的方法的特殊召唤1回合只能有1次。 ①：双方场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡上级召唤成功时，以自己墓地1只4星以下的「疾行机人」怪兽为对象才能发动。那只怪兽特殊召唤。 ③：只要这张卡在怪兽区域存在，对方不能选择其他的「疾行机人」怪兽作为攻击对象。'),
(80559548, 'Speedroid Razorang', '疾行机人 变形回力镖', 'SRシェイブー・メラン', 'Effect Monster', 'Machine', 'WIND', 4, 2000, NULL, '①：这张卡在召唤的回合不能攻击。 ②：1回合1次，以场上1只表侧表示怪兽为对象才能发动。这张卡变成守备表示，作为对象的怪兽的攻击力直到回合结束时下降800。'),
(16725505, 'Speedroid Red-Eyed Dice', '疾行机人 红眼骰子', 'SR赤目のダイス', 'Tuner Monster', 'Machine', 'WIND', 1, 100, 100, '①：这张卡召唤·特殊召唤成功时，以「疾行机人 赤目骰子」以外的自己场上1只「疾行机人」怪兽为对象，宣言1～6的任意等级才能发动。那只怪兽的等级直到回合结束时变成宣言的等级。'),
(8284390, 'Speedroid Rubberband Plane', '疾行机人 橡筋动力飞机', 'SR５６プレーン', 'Effect Monster', 'Machine', 'WIND', 5, 1800, NULL, '「疾行机人 56飞机」的①的效果1回合只能使用1次。 ①：自己场上有怪兽特殊召唤的场合才能发动。这张卡从手卡特殊召唤。这个效果的发动后，直到回合结束时自己不是风属性怪兽不能特殊召唤。 ②：这张卡召唤·特殊召唤成功的场合，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时下降600。'),
(29114773, 'Speedroid Scratch', '疾行机人刮刮乐', 'SRスクラッチ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从手卡把1张「疾行机人」卡送去墓地才能发动。从卡组把1只「疾行机人」怪兽加入手卡。'),
(35494087, 'Speedroid Skull Marbles', '疾行机人 噗噗噔骷髅', 'SRビードロ・ドクロ', 'Effect Monster', 'Machine', 'WIND', 7, NULL, 3000, '「疾行机人 噗噗噔骷髅」的③的效果1回合只能使用1次。 ①：自己·对方的准备阶段，从额外卡组特殊召唤的怪兽在对方场上存在的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡不会被和通常召唤的怪兽的战斗破坏。 ③：这张卡的战斗发生的对自己的战斗伤害由对方代受。 ④：自己场上有「疾行机人」怪兽以外的表侧表示怪兽存在的场合这张卡破坏。'),
(53932291, 'Speedroid Taketomborg', '疾行机人 竹蜻蜓博格', 'SRタケトンボーグ', 'Effect Monster', 'Machine', 'WIND', 3, 600, 1200, '自己对「疾行机人 竹蜻蜓电子人」1回合只能有1次特殊召唤。 ①：自己场上有风属性怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：把这张卡解放才能发动。从卡组把1只「疾行机人」调整特殊召唤。这个效果的发动后，直到回合结束时自己不是风属性怪兽不能特殊召唤。'),
(81275020, 'Speedroid Terrortop', '疾行机人 贝陀螺飞轮', 'SRベイゴマックス', 'Effect Monster', 'Machine', 'WIND', 3, 1200, 600, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡召唤·特殊召唤成功时才能发动。从卡组把「疾行机人 贝陀螺集合体」以外的1只「疾行机人」怪兽加入手卡。'),
(27660735, 'Speedroid Tri-Eyed Dice', '疾行机人 三目骰子', 'SR三つ目のダイス', 'Tuner Monster', 'Machine', 'WIND', 3, 300, 1500, '①：对方回合把墓地的这张卡除外才能发动。这个回合，对方怪兽的攻击只有1次无效。'),
(86976918, 'Speedroid Ultra Hound', '疾行机人 伸缩弹簧狗', 'SRマジックハウンド', 'Effect Monster', 'Machine', 'WIND', 3, 800, 800, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡召唤成功时才能发动。从卡组把1张「疾行机人」卡送去墓地。 ②：把墓地的这张卡除外，以自己墓地1只「疾行机人」怪兽为对象才能发动。那只怪兽回到卡组，和那只怪兽是卡名不同并是等级相同的1只「疾行机人」同调怪兽效果无效从额外卡组特殊召唤。这个效果在这张卡送去墓地的回合不能发动。'),
(12148078, 'Speedroid Wheel', '疾行机人轮盘', 'SRルーレット', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：丢弃1张手卡才能发动。掷1次骰子。等级合计直到变成和出现的数目相同为止从手卡·卡组把最多2只「疾行机人」怪兽效果无效特殊召唤。没能特殊召唤的场合，自己失去出现的数目×500基本分。'),
(2254222, 'Speedroid Wing Synchron', '疾行机人 翼同步士', 'SRウィング・シンクロン', 'Pendulum Tuner Effect Monster', 'Machine', 'WIND', 5, 1500, 1000, '这个卡名的怪兽效果1回合只能使用1次。 ①：这张卡表侧加入额外卡组的场合，若自己场上的风属性同调怪兽的种族是2种类以上则能发动。从卡组把1张「疾行机人」魔法·陷阱卡送去墓地。'),
(51481927, 'Spell Absorption', '魔法吸收', '魔法吸収', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，每次自己或者对方把魔法卡发动，自己回复500基本分。'),
(41160595, 'Spell Calling', '神召魔法', 'コーリング・マジック', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '对方控制的魔法·陷阱卡的效果把盖放的这张卡破坏送去墓地时，从卡组选择1张速攻魔法卡给双方确认并在自己场上盖放。'),
(84636823, 'Spell Canceller', '魔术抵消器', 'マジック・キャンセラー', 'Effect Monster', 'Machine', 'WIND', 5, 1800, 1600, '只要这张卡在场上表侧表示存在，魔法卡不能发动，场上所有魔法卡的效果无效化。'),
(28958464, 'Spell Card "Monster Reborn"', '魔法卡“死者苏生”', 'マジックカード「死者蘇生」', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己或对方的墓地1只怪兽为对象才能发动。那只怪兽在自己场上特殊召唤。这个回合，这个效果特殊召唤的怪兽不能攻击，那个效果不能发动。'),
(15735108, 'Spell Card "Soul Exchange"', '魔法卡“灵魂交换”', 'マジックカード「クロス・ソウル」', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：进行1只怪兽的上级召唤。那个时候，也能作为自己场上的怪兽的代替而把对方场上的怪兽解放。这个效果上级召唤的怪兽在这个回合不能解放。 ②：这张卡从场上送去墓地的场合发动。对方可以让这张卡的①的效果适用。'),
(74402414, 'Spell Chronicle', '魔法编年史', 'マジック・クロニクル', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：把手卡全部送去墓地才能把这张卡发动。从卡组把5张魔法·陷阱卡除外。 ②：每次对方把魔法卡发动，给这张卡放置1个年代记指示物。 ③：把这张卡2个年代记指示物取除才能发动。对方从这张卡的效果除外的卡之中选1张。自己把那张卡加入手卡。 ④：魔法与陷阱区域的表侧表示的这张卡从场上离开时，自己受到这张卡的效果除外中的卡数量×500伤害。'),
(4259068, 'Spell Economics', '魔力俭约术', '魔力倹約術', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '发动魔法卡时不需支付基本分。'),
(313513, 'Spell Gear', '魔法齿车', '魔法の歯車', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上3张表侧表示的「古代的机械」卡送去墓地才能发动。从手卡以及卡组各把最多1只「古代的机械巨人」无视召唤条件特殊召唤。那之后，自己场上有「古代的机械巨人」以外的怪兽存在的场合，那些怪兽全部破坏。这个效果的发动后，用自己回合计算的2回合内，自己不能通常召唤。'),
(300302018, 'Spell of Mask', NULL, NULL, 'Skill Card', 'Lumis Umbra', NULL, NULL, NULL, NULL, NULL),
(300302053, 'Spell of Mask (Skill Card)', NULL, NULL, 'Skill Card', 'Lumis and Umb', NULL, NULL, NULL, NULL, NULL),
(76714458, 'Spell of Pain', '痛魂之咒术', '痛魂の呪術', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：给与自己伤害的效果由对方发动时才能发动。那个效果发生的对自己的效果伤害由对方代受。'),
(75014062, 'Spell Power Grasp', '魔力掌握', '魔力掌握', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以场上1张可以放置魔力指示物的卡为对象才能发动。给那张卡放置1个魔力指示物。那之后，可以从卡组把1张「魔力掌握」加入手卡。'),
(38943357, 'Spell Power Mastery', '魔力统辖', '魔力統轄', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把1张「恩底弥翁」卡加入手卡。那之后，可以给自己场上的可以放置魔力指示物的卡尽可能放置最多有自己的场上·墓地的「魔力统辖」「魔力掌握」数量的魔力指示物。'),
(300103002, 'Spell Proof Armor', NULL, NULL, 'Skill Card', 'Keith', NULL, NULL, NULL, NULL, NULL),
(1669772, 'Spell Purification', '魔力净化', '魔力浄化', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '丢弃1张手卡。场上表侧表示存在的永续魔法全部破坏。'),
(15175429, 'Spell Reactor RE', '魔法反应机·袭式', 'マジック・リアクター・AID', 'Effect Monster', 'Machine', 'DARK', 3, 1200, 900, '对方把魔法卡发动时才能发动。把那张魔法卡破坏，给与对方基本分800分伤害。这个效果1回合只能使用1次。'),
(76137276, 'Spell Reclamation', '魔法捕获', 'マジック・キャプチャー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己把魔法卡发动时，丢弃1张手卡连锁发动。连锁发动的魔法卡被送去墓地时，那张卡回到手卡。'),
(45118716, 'Spell Recycler', '魔法回收士', 'マジック・リサイクラー', 'Effect Monster', 'Spellcaster', 'DARK', 1, NULL, NULL, '对方怪兽的攻击宣言时把墓地的这张卡从游戏中除外，选择自己墓地1张魔法卡才能发动。自己卡组最上面的卡送去墓地，选择的卡回到卡组最下面。'),
(29228529, 'Spell Reproduction', '魔法再生', '魔法再生', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '将自己手卡中的2张魔法卡送去墓地。从自己墓地里选择1张魔法卡加入手卡。'),
(93260132, 'Spell Shattering Arrow', '魔法效果之矢', '魔法効果の矢', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：对方场上的表侧表示的魔法卡全部破坏，给与对方破坏数量×500伤害。'),
(38275183, 'Spell Shield Type-8', '八式对魔法多重结界', '八式対魔法多重結界', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '从下列效果中选择1项发动： ●使1张以场上1只怪兽为对象的魔法卡的发动与效果无效，并且把它破坏。 ●从手卡把1张魔法卡送去墓地。使1张魔法卡的发动与效果无效，并且把它破坏。'),
(93966624, 'Spell Strider', '魔法进击者', 'マジック・ストライダー', 'Effect Monster', 'Warrior', 'EARTH', 4, 1800, 600, '①：这张卡在手卡存在的场合，以自己以及对方场上的表侧表示的魔法卡各1张为对象才能发动。那些卡除外，这张卡从手卡特殊召唤。'),
(93187568, 'Spell Striker', '魔法攻击士', 'マジック・ストライカー', 'Effect Monster', 'Warrior', 'EARTH', 3, 600, 200, '①：这张卡可以把自己墓地1张魔法卡除外，从手卡特殊召唤。 ②：这张卡可以直接攻击。 ③：这张卡的战斗发生的对自己的战斗伤害变成0。'),
(29735721, 'Spell Vanishing', '咒术抹消', '呪術抹消', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '丢弃2张手卡。使魔法卡的发动无效，并且将其破坏。确认对方的手卡及卡组，若存在与被破坏的魔法卡同名的卡，将其全部送去墓地。'),
(84117021, 'Spell Wall', '魔力隔壁', '魔力隔壁', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：可以从以下效果选择1个发动。这张卡的发动后，直到回合结束时对方受到的全部伤害变成0。 ●这个回合，魔法师族怪兽的召唤·反转召唤·特殊召唤不会被无效化，在魔法师族怪兽的召唤·反转召唤·特殊召唤成功时对方不能把魔法·陷阱·怪兽的效果发动。 ●以自己场上1只魔法师族怪兽为对象才能发动。这个回合那只怪兽攻击的场合，对方直到伤害步骤结束时魔法·陷阱·怪兽的效果不能发动。'),
(10069180, 'Spell-Stopping Statute', '魔力终了宣告', '魔力終了宣告', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '对方发动永续魔法卡时才能发动。那张卡的发动和效果无效，并且破坏。'),
(18807109, 'Spellbinding Circle', '六芒星之咒缚', '六芒星の呪縛', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, NULL),
(40230018, 'Spellbook Library of the Crescent', '魔导书库 科瑞森', '魔導書庫クレッセン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己墓地没有名字带有「魔导书」的魔法卡存在的场合才能发动。从卡组选名字带有「魔导书」的魔法卡3种类给对方观看，对方从那之中随机选1张。对方选的1张卡加入自己手卡，剩下的卡回到卡组。「魔导书库 科瑞森」在1回合只能发动1张，这张卡发动的回合，自己不能把名字带有「魔导书」的卡以外的魔法卡发动。'),
(20822520, 'Spellbook Library of the Heliosphere', '魔导书库 苏雷', '魔導書庫ソレイン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己墓地的名字带有「魔导书」的魔法卡是5张以上的场合才能发动。从自己卡组上面把2张卡翻开。那之中的名字带有「魔导书」的魔法卡全部加入手卡，剩下的卡回到卡组。「魔导书库 苏雷」在1回合只能发动1张，这张卡发动的回合，自己不能把名字带有「魔导书」的卡以外的魔法卡发动。'),
(14824019, 'Spellbook Magician of Prophecy', '魔导书士 巴泰尔', '魔導書士 バテル', 'Effect Monster', 'Spellcaster', 'WATER', 2, 500, 400, '①：这张卡召唤·反转的场合发动。从卡组把1张「魔导书」魔法卡加入手卡。'),
(61592395, 'Spellbook of Eternity', '蜡板之魔导书', 'アルマの魔導書', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择「蜡板之魔导书」以外的从游戏中除外的1张自己的名字带有「魔导书」的魔法卡加入手卡。「蜡板之魔导书」在1回合只能发动1张。'),
(97997309, 'Spellbook of Fate', '恶灵之魔导书', 'ゲーテの魔導書', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '自己场上有魔法师族怪兽存在的场合，把自己墓地最多3张名字带有「魔导书」的魔法卡从游戏中除外才能发动。为这张卡发动而除外的魔法卡数量的以下效果适用。「恶灵之魔导书」在1回合只能发动1张。 ●1张：选场上盖放的1张魔法·陷阱卡回到持有者手卡。 ●2张：选场上1只怪兽变成里侧守备表示或者表侧攻击表示。 ●3张：选对方场上1张卡从游戏中除外。'),
(46448938, 'Spellbook of Judgment', '魔导书的神判', '魔導書の神判', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：这张卡发动的回合的结束阶段，把最多有这张卡的发动后自己或者对方发动的魔法卡数量的「魔导书的神判」以外的「魔导书」魔法卡从卡组加入手卡。那之后，可以把持有这个效果加入手卡的卡数量以下的等级的1只魔法师族怪兽从卡组特殊召唤。'),
(23314220, 'Spellbook of Knowledge', '噶尔德之魔导书', 'ルドラの魔導書', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：「冰火之魔导书」以外的自己的手卡·场上（表侧表示）1张「魔导书」卡或者自己场上1只表侧表示的魔法师族怪兽送去墓地，自己抽2张。'),
(52628687, 'Spellbook of Life', '死灵之魔导书', 'ネクロの魔導書', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '把自己墓地1只魔法师族怪兽从游戏中除外，把这张卡以外的手卡1张名字带有「魔导书」的魔法卡给对方观看才能发动。选择自己墓地1只魔法师族怪兽表侧攻击表示特殊召唤，把这张卡装备。此外，装备怪兽的等级上升因为这张卡发动而除外的魔法师族怪兽的等级数值。「死灵之魔导书」在1回合只能发动1张。'),
(43841694, 'Spellbook of Miracles', '魔导书的奇迹', '魔導書の奇跡', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己墓地1只魔法师族超量怪兽和从游戏中除外的最多2张自己的名字带有「魔导书」的魔法卡才能发动。选择的怪兽特殊召唤，把选择的名字带有「魔导书」的魔法卡在那只怪兽下面重叠作为超量素材。「魔导书的奇迹」在1回合只能发动1张。'),
(25123082, 'Spellbook of Power', '水卜之魔导书', 'ヒュグロの魔導書', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只魔法师族怪兽为对象才能发动。这个回合，那只怪兽的攻击力上升1000，以下效果适用。 ●那只怪兽战斗破坏对方怪兽时才能发动。从卡组把1张「魔导书」魔法卡加入手卡。'),
(89739383, 'Spellbook of Secrets', '格里莫之魔导书', 'グリモの魔導書', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把「奥义之魔导书」以外的1张「魔导书」卡加入手卡。');